const cache = new Map();                        // swap for an LRU/TTL cache in production

async function enrich(msg, source) {
  let customer = cache.get(msg.customerId);
  if (!customer) {
    customer = await source.find(msg.customerId);
    cache.set(msg.customerId, customer);
  }
  return { ...msg, customerName: customer?.name, region: customer?.region };
}
